#undef rohc_buf_init_full
#undef rohc_buf_init_empty
static rohc_buf full_buf(uint8_t *data, size_t len, rohc_ts time){rohc_buf b{};b.time=time;b.data=data;b.max_len=len;b.len=len;return b;}
static rohc_buf empty_buf(uint8_t *data, size_t len){rohc_buf b{};b.data=data;b.max_len=len;return b;}
#define rohc_buf_init_full(data,len,time) full_buf((data),(len),(time))
#define rohc_buf_init_empty(data,len) empty_buf((data),(len))
enum class P{RTP,UDP,ESP,IP};struct Packet{std::vector<std::uint8_t>b;};
static std::uint16_t sum(const std::uint8_t*p,std::size_t n){std::uint32_t s=0;for(std::size_t i=0;i<n;i+=2){s+=std::uint16_t(p[i])<<8;if(i+1<n)s+=p[i+1];}while(s>>16)s=(s&65535)+(s>>16);return std::uint16_t(~s);}static void p16(std::uint8_t*p,std::uint16_t v){p[0]=v>>8;p[1]=v;}static void p32(std::uint8_t*p,std::uint32_t v){p[0]=v>>24;p[1]=v>>16;p[2]=v>>8;p[3]=v;}static const char*n(P p){return p==P::RTP?"rtp_udp_ipv4":p==P::UDP?"udp_ipv4":p==P::ESP?"esp_ipv4":"ip_only_ipv4";}
static Packet make(P q,std::uint32_t flow,std::uint32_t i){std::size_t h=q==P::RTP?40:(q==P::UDP||q==P::ESP?28:20);Packet x;x.b.assign(h+160,0);auto*p=x.b.data();p[0]=0x45;p16(p+2,x.b.size());p16(p+4,i);p16(p+6,0x4000);p[8]=64;p[9]=q==P::RTP||q==P::UDP?17:q==P::ESP?50:253;p[12]=10;p[14]=flow;p[15]=1;p[16]=10;p[18]=flow;p[19]=2;if(q==P::RTP||q==P::UDP){p16(p+20,10000+flow);p16(p+22,20000+flow);p16(p+24,x.b.size()-20);}if(q==P::RTP){p[28]=0x80;p[29]=96;p16(p+30,1000+i);p32(p+32,160000+i*160);p32(p+36,0x11223300+flow);}if(q==P::ESP){p32(p+20,0x10203000+flow);p32(p+24,i);}std::uint64_t s=0x524f484343585832ULL^(std::uint64_t(flow)<<32)^i;for(std::size_t j=h;j<x.b.size();j++){s^=s<<13;s^=s>>7;s^=s<<17;p[j]=s;}p16(p+10,sum(p,20));return x;}
static std::vector<Packet> corpus(P p){std::vector<Packet>v;for(std::uint32_t i=0;i<256;i++){auto x=make(p,0,i);if(p==P::UDP)x.b[28]&=0x3f;v.push_back(std::move(x));}return v;}static bool rtp(const unsigned char*,const unsigned char*,const unsigned char*p,unsigned int z,void*){return z>=12&&(p[0]>>6)==2;}static int rnd(const struct rohc_comp*,void*){return 0x5a;}
struct LC{void operator()(::rohc_comp*p)const{::rohc_comp_free(p);}};struct LD{void operator()(::rohc_decomp*p)const{::rohc_decomp_free(p);}};
static bool lib(P p,const std::vector<Packet>&v,std::uint64_t&bytes){std::unique_ptr<::rohc_comp,LC>c(::rohc_comp_new2(ROHC_SMALL_CID,15,rnd,nullptr));std::unique_ptr<::rohc_decomp,LD>d(::rohc_decomp_new2(ROHC_SMALL_CID,15,ROHC_U_MODE));if(!c||!d)return false;const auto id=static_cast<rohc_profile_t>(p==P::RTP?ROHC_PROFILE_RTP:p==P::UDP?ROHC_PROFILE_UDP:p==P::ESP?ROHC_PROFILE_ESP:ROHC_PROFILE_IP);if(p==P::RTP&&!::rohc_comp_set_rtp_detection_cb(c.get(),rtp,nullptr))return false;if(!::rohc_comp_enable_profile(c.get(),static_cast<rohc_profile_t>(id))||!::rohc_decomp_enable_profile(d.get(),static_cast<rohc_profile_t>(id)))return false;bytes=0;std::array<std::uint8_t,4098>z{},o{};for(std::size_t i=0;i<v.size();i++){z.front()=0xa5;z.back()=0x5a;o.front()=0x3c;o.back()=0xc3;rohc_ts ts{static_cast<uint64_t>(i),0};auto in=rohc_buf_init_full(const_cast<uint8_t*>(v[i].b.data()),v[i].b.size(),ts);auto co=rohc_buf_init_empty(z.data()+1,4096);if(::rohc_compress4(c.get(),in,&co)!=ROHC_STATUS_OK||z.front()!=0xa5||z.back()!=0x5a)return false;bytes+=co.len;auto ci=rohc_buf_init_full(co.data,co.len,ts);auto uo=rohc_buf_init_empty(o.data()+1,4096);if(::rohc_decompress3(d.get(),ci,&uo,nullptr,nullptr)!=ROHC_STATUS_OK||o.front()!=0x3c||o.back()!=0xc3||uo.len!=v[i].b.size()||std::memcmp(uo.data,v[i].b.data(),uo.len))return false;}return true;}
static bool xx(const std::vector<Packet>&v,std::uint64_t&bytes){const char*path=std::getenv("ROHCCXX_SO");if(!path)return false;void*h=dlopen(path,RTLD_NOW|RTLD_LOCAL);if(!h)return false;using New=void*(*)(std::uint32_t,int);using Free=void(*)(void*);using Set=int(*)(void*,std::uint32_t);using Comp=int(*)(void*,const std::uint8_t*,std::size_t,std::uint8_t*,std::size_t*);using Dec=Comp;auto nc=(New)dlsym(h,"rohc_comp_new2"),nd=(New)dlsym(h,"rohc_decomp_new2");auto fc=(Free)dlsym(h,"rohc_comp_free"),fd=(Free)dlsym(h,"rohc_decomp_free");auto set=(Set)dlsym(h,"rohc_comp_set_cid");auto comp=(Comp)dlsym(h,"rohc_compress4"),dec=(Dec)dlsym(h,"rohc_decompress4");if(!nc||!nd||!fc||!fd||!set||!comp||!dec){dlclose(h);return false;}void*c=nc(0,0),*d=nd(0,0);if(!c||!d){if(c)fc(c);if(d)fd(d);dlclose(h);return false;}bytes=0;bool ok=true;std::array<std::uint8_t,4098>z{},o{};for(std::size_t i=0;i<v.size()&&ok;i++){z.front()=0xa5;z.back()=0x5a;o.front()=0x3c;o.back()=0xc3;std::size_t zn=4096,on=4096;ok=!set(c,0)&&!comp(c,v[i].b.data(),v[i].b.size(),z.data()+1,&zn)&&z.front()==0xa5&&z.back()==0x5a;if(!ok)break;bytes+=zn;ok=!dec(d,z.data()+1,zn,o.data()+1,&on)&&o.front()==0x3c&&o.back()==0xc3&&on==v[i].b.size()&&!std::memcmp(o.data()+1,v[i].b.data(),on);}fc(c);fd(d);dlclose(h);return ok;}
static bool control(const std::vector<Packet>&v,std::uint64_t&bytes){bytes=0;std::array<std::uint8_t,4098>o{};for(auto&x:v){o.front()=0x3c;o.back()=0xc3;std::memcpy(o.data()+1,x.b.data(),x.b.size());bytes+=x.b.size();if(o.front()!=0x3c||o.back()!=0xc3||std::memcmp(o.data()+1,x.b.data(),x.b.size()))return false;}return true;}
int main(int c,char**a){if(c!=2||std::string(a[1])!="validate"){std::cerr<<"timing requires reviewed manifest runner\n";return 64;}bool all=true;for(P p:{P::RTP,P::UDP,P::ESP,P::IP}){auto v=corpus(p);for(int pass=0;pass<2;pass++){std::uint64_t xb=0,lb=0,cb=0;bool x=xx(v,xb),l=lib(p,v,lb),m=control(v,cb);std::cout<<"VALIDATION,"<<n(p)<<",pass="<<pass<<",rohccxx="<<(x?"PASS":"FAIL")<<",rohclib="<<(l?"PASS":"FAIL")<<",control="<<(m?"PASS":"FAIL")<<",packets=256,rohccxx_bytes="<<xb<<",rohclib_bytes="<<lb<<",input_bytes="<<cb<<",guards="<<((x&&l&&m)?0:1)<<"\n";all&=x&&l&&m;}}return all?0:2;}
